def asn1_length(length):
    if length < 128:
        return bytes([length])
    elif length < 256:
        return bytes([0x81, length])
    else:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])

def asn1_tag_length_value(tag, value):
    return bytes([tag]) + asn1_length(len(value)) + value

def asn1_sequence(content):
    return asn1_tag_length_value(0x30, content)

def asn1_int(value):
    if value == 0:
        return asn1_tag_length_value(0x02, b'\x00')
    val_bytes = value.to_bytes((value.bit_length() + 7) // 8, 'big')
    if val_bytes[0] & 0x80:
        val_bytes = b'\x00' + val_bytes
    return asn1_tag_length_value(0x02, val_bytes)

def asn1_oid(oid_str):
    parts = [int(x) for x in oid_str.split('.')]
    result = bytes([40 * parts[0] + parts[1]])
    for part in parts[2:]:
        if part < 128:
            result += bytes([part])
        else:
            encoded = []
            while part > 0:
                encoded.insert(0, (part & 0x7f) | (0x80 if len(encoded) > 0 else 0))
                part >>= 7
            result += bytes(encoded)
    return asn1_tag_length_value(0x06, result)

def asn1_utf8string(s):
