serial = asn1_int(1)
sig_alg_oid = asn1_oid('1.2.840.113549.1.1.11')
sig_alg = asn1_sequence(sig_alg_oid + asn1_tag_length_value(0x05, b''))

name_component = asn1_sequence(asn1_sequence(asn1_oid('2.5.4.3') + asn1_utf8string('Test')))
issuer = asn1_sequence(name_component)
subject = asn1_sequence(name_component)

validity = asn1_sequence(
