    asn1_utctime('240101000000Z')
)

modulus = asn1_int(0x010001)
exponent = asn1_int(65537)
rsa_key = asn1_sequence(modulus + exponent)
pubkey_alg = asn1_sequence(asn1_oid('1.2.840.113549.1.1.1') + asn1_tag_length_value(0x05, b''))
pubkey = asn1_sequence(pubkey_alg + asn1_bitstring(rsa_key))

# SAN extension with 3 entries
# Entry 1: valid dNSName
dns1 = asn1_tag_length_value(0x82, b'example.com')

# Entry 2: valid dNSName  
dns2 = asn1_tag_length_value(0x82, b'test.com')

# Entry 3: malformed otherName with HwModuleName OID
# OID: 1.3.6.1.5.5.7.8.4
hwmodule_oid = asn1_oid('1.3.6.1.5.5.7.8.4')

# Create malformed otherName structure
# otherName should contain: OID, then [0] EXPLICIT SEQUENCE { OID, OCTET STRING }
# We'll make it fail at the first mbedtls_asn1_get_tag call (line 1672)
# by having the OID but then an invalid tag instead of the expected structure

# This will be wrapped in context-specific [0] for otherName
# The content should start with an OID, but we'll make it truncated/invalid
malformed_other_content = hwmodule_oid[:3]  # Truncated OID to trigger parse error

other_name = asn1_tag_length_value(0xa0, malformed_other_content)

# GeneralNames SEQUENCE
san_sequence = asn1_sequence(dns1 + dns2 + other_name)

# SAN extension
san_oid = asn1_oid('2.5.29.17')
